const supabaseCdn='    <script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script>\n\n';
if(!html.includes('cdn.jsdelivr.net/npm/@supabase/supabase-js@2')){
  html=html.replace('    <!-- JAVASCRIPT LOGIK -->\n    \n    <script>', '    <!-- JAVASCRIPT LOGIK -->\n    '+supabaseCdn+'    <script>');
}

const oldBlockStart="        const RSVP_API_URL = 'http://localhost:3000/api/rsvp';";
const oldBlockEnd='        const translations = {';
const startIdx=html.indexOf(oldBlockStart);
const endIdx=html.indexOf(oldBlockEnd);
if(startIdx===-1 || endIdx===-1 || endIdx<=startIdx){ throw new Error('Could not locate old API block'); }
const newBlock=`        const SUPABASE_CONFIG = {
            url: window.SUPABASE_CONFIG?.url || 'https://YOUR_PROJECT_ID.supabase.co',
            anonKey: window.SUPABASE_CONFIG?.anonKey || 'YOUR_SUPABASE_ANON_KEY',
            table: window.SUPABASE_CONFIG?.table || 'rsvp_responses'
        };

        function isSupabaseConfigValid(config) {
            if (!config || typeof config !== 'object') return false;
            const hasUrl = typeof config.url === 'string' && config.url.startsWith('https://') && !config.url.includes('YOUR_PROJECT_ID');
            const hasKey = typeof config.anonKey === 'string' && config.anonKey.length > 20 && !config.anonKey.includes('YOUR_SUPABASE_ANON_KEY');
            return hasUrl && hasKey;
        }

        function createSupabaseClient() {
            if (!window.supabase || typeof window.supabase.createClient !== 'function') {
                throw new Error('Supabase-Bibliothek konnte nicht geladen werden. Bitte Seite neu laden.');
            }

            if (!isSupabaseConfigValid(SUPABASE_CONFIG)) {
                throw new Error('Supabase-Konfiguration fehlt oder ist ungueltig. Bitte URL und anon Key korrekt setzen.');
            }

            return window.supabase.createClient(SUPABASE_CONFIG.url, SUPABASE_CONFIG.anonKey, {
                auth: {
                    persistSession: false,
                    autoRefreshToken: false,
                    detectSessionInUrl: false
                }
            });
        }

        function normalizeRsvpPayload(payload) {
            const attendanceStatus = payload.attendance === 'declined' ? 'declined' : 'attending';
            const hasPlusOne = attendanceStatus === 'attending' ? Boolean(payload.hasPlusOne) : false;
            const plusOneName = hasPlusOne ? (payload.plusOneName || '').trim() : null;

            return {
                full_name: (payload.fullName || '').trim(),
                email: (payload.email || '').trim().toLowerCase(),
                phone: (payload.phone || '').trim() || null,
                attendance_status: attendanceStatus,
                has_plus_one: hasPlusOne,
                plus_one_name: plusOneName || null,
                song_request: (payload.songRequest || '').trim() || null,
                message: (payload.message || '').trim() || null,
                client_timestamp: payload.timestamp || new Date().toISOString()
            };
        }

        function mapSupabaseError(error) {
            const message = String(error?.message || '').toLowerCase();

            if (error?.code === '42501' || message.includes('row-level security') || message.includes('permission denied')) {
                return 'Der Zugriff auf die RSVP-Tabelle wurde durch RLS blockiert. Bitte Supabase Policy pruefen.';
            }

            if (error?.code === '42P01' || message.includes('relation') && message.includes('does not exist')) {
                return 'Die konfigurierte RSVP-Tabelle wurde nicht gefunden. Bitte Tabellenname und Schema pruefen.';
            }

            if (message.includes('invalid api key') || message.includes('jwt') || message.includes('unauthorized') || message.includes('forbidden')) {
                return 'Supabase-Anmeldedaten sind ungueltig. Bitte anon Key und Projekt-URL pruefen.';
            }

            if (message.includes('failed to fetch') || message.includes('network')) {
                return 'Netzwerkfehler beim Senden. Bitte Verbindung und Supabase-URL pruefen.';
            }

            return null;
        }

        async function submitToSupabase(payload) {
            const client = createSupabaseClient();
            const row = normalizeRsvpPayload(payload);
            const { error } = await client.from(SUPABASE_CONFIG.table).insert([row]);

            if (error) {
                const mappedMessage = mapSupabaseError(error);
                if (mappedMessage) {
                    throw new Error(mappedMessage);
                }
                throw new Error('RSVP konnte nicht gespeichert werden. Bitte spaeter erneut versuchen.');
            }

            return { ok: true };
        }

`;
