            updateKpis(filteredRows);
            renderRows(filteredRows);
            setDashboardStatus("Showing " + filteredRows.length + " of " + allRows.length + " rows.");
        }

        async function loadResponses() {
            if (!supabaseClient) return;
            setDashboardStatus("Lade RSVP Daten...");

            const { data, error } = await supabaseClient
                .from(SUPABASE_CONFIG.table)
                .select("created_at, full_name, email, phone, attendance_status, has_plus_one, plus_one_name, song_request, message")
                .order("created_at", { ascending: false });

            if (error) {
                setDashboardStatus("Loading failed: " + (error.message || "Unknown error"), true);
                return;
            }

            allRows = Array.isArray(data) ? data : [];
            applyFilters();
            setDashboardStatus("Data loaded.");
        }

        async function handleLoginSubmit(event) {
            event.preventDefault();
            if (!supabaseClient) return;

            const formData = new FormData(loginForm);
            const email = String(formData.get("email") || "").trim();
            const password = String(formData.get("password") || "");

            if (!email || !password) {
                setLoginStatus("Bitte E-Mail und Passwort eingeben.", true);
                return;
            }

            setLoadingLogin(true);
            setLoginStatus("Authenticating...");

            const { error } = await supabaseClient.auth.signInWithPassword({ email, password });

            if (error) {
                setLoadingLogin(false);
                setLoginStatus("Login failed: " + (error.message || "Unknown error"), true);
                return;
            }

            setLoginStatus("Login successful.");
            setLoadingLogin(false);
        }

        async function handleLogout() {
            if (!supabaseClient) return;
            const { error } = await supabaseClient.auth.signOut();
            if (error) {
                setDashboardStatus("Logout failed: " + (error.message || "Unknown error"), true);
                return;
            }
            setDashboardStatus("Logged out.");
        }

        async function syncWithSession() {
            if (!supabaseClient) return;
            const { data, error } = await supabaseClient.auth.getSession();
            if (error) {
                setLoginStatus("Session check failed: " + (error.message || "Unknown error"), true);
                setDashboardVisibility(false);
                return;
            }

            const session = data?.session;
            if (session?.user) {
                setDashboardVisibility(true, session.user.email || "(no email)");
                await loadResponses();
            } else {
                setDashboardVisibility(false);
                setLoginStatus("Bitte einloggen, um RSVPs zu sehen.");
            }
        }

        async function init() {
            try {
                supabaseClient = createSupabaseClient();
            } catch (error) {
                const message = error instanceof Error ? error.message : "Supabase setup error";
                configError.textContent = message + " Configure window.SUPABASE_CONFIG with url and anonKey.";
                configError.classList.remove("hidden");
                loginCard.classList.add("hidden");
                dashboard.classList.add("hidden");
                return;
            }

            loginForm.addEventListener("submit", handleLoginSubmit);
            logoutBtn.addEventListener("click", handleLogout);
            refreshBtn.addEventListener("click", loadResponses);
            searchInput.addEventListener("input", applyFilters);
            statusFilter.addEventListener("change", applyFilters);
            exportBtn.addEventListener("click", exportFilteredToCsv);

            supabaseClient.auth.onAuthStateChange(async (_event, session) => {
                if (session?.user) {
                    setDashboardVisibility(true, session.user.email || "(no email)");
                    await loadResponses();
                } else {
                    setDashboardVisibility(false);
                }
            });

            await syncWithSession();
        }

        init();
    </script>
</body>
</html>
EOF

